import java.util.HashSet;
import java.util.List;
import java.util.Set;

public class NavalBattleAdapter {
    private final Set<String> shipPositions;
    private final Set<String> attackPositions;

    public NavalBattleAdapter() {
        this.shipPositions = new HashSet<>();
        this.attackPositions = new HashSet<>();
    }

    public void placeShips(List<String> coordinates) {
        if (coordinates != null) {
            shipPositions.addAll(coordinates);
        }
    }

    public HitResult receiveAttack(String coordinate) {
        attackPositions.add(coordinate);
        return shipPositions.contains(coordinate)
                ? HitResult.HIT
                : HitResult.MISS;
    }
}

enum HitResult {
    HIT,
    MISS
}

