    private final Set<String> remainingShips;
    private final Set<String> attacksMade;
    private final boolean gameOver;
    private final String winner;

    public GameState(
            Set<String> remainingShips,
            Set<String> attacksMade,
            boolean gameOver,
            String winner
    ) {
        this.remainingShips = Collections.unmodifiableSet(new HashSet<>(remainingShips));
        this.attacksMade = Collections.unmodifiableSet(new HashSet<>(attacksMade));
        this.gameOver = gameOver;
        this.winner = winner;
