import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.LinkedHashMap;
import java.util.Locale;
import java.util.Map;
import java.util.stream.Stream;

public class AdvancedFileProcessor {
    private final Path directory;

    public AdvancedFileProcessor(String directoryPath) {
        this.directory = Paths.get(directoryPath);

        if (!Files.isDirectory(this.directory)) {
            throw new IllegalArgumentException("Provided path is not a directory: " + directoryPath);
        }
    }

    public Map<String, Object> processFiles() {
        Map<String, Object> statistics = new LinkedHashMap<>();
        Map<String, Integer> wordFrequency = new LinkedHashMap<>();

        int fileCount = 0;
        long totalSize = 0L;
        long largestFileSize = -1L;
        String largestFile = "N/A";

        try (Stream<Path> files = Files.walk(directory)) {
            for (Path file : (Iterable<Path>) files.filter(Files::isRegularFile)::iterator) {
                long fileSize = Files.size(file);

                fileCount++;
                totalSize += fileSize;

                if (fileSize > largestFileSize) {
                    largestFileSize = fileSize;
                    largestFile = file.getFileName().toString();
                }

                processFileContent(file, wordFrequency);
            }
        } catch (IOException e) {
            throw new UncheckedIOException("Failed to process files in: " + directory, e);
        }

        statistics.put("fileCount", fileCount);
        statistics.put("totalSize", totalSize);
        statistics.put("largestFile", largestFile);
        statistics.put("wordFrequency", wordFrequency);

        return statistics;
    }

    private void processFileContent(Path file, Map<String, Integer> wordFrequency)
            throws IOException {
        String content = new String(Files.readAllBytes(file), StandardCharsets.UTF_8);

        for (String word : content.split("\\s+")) {
            String normalizedWord = word
                    .toLowerCase(Locale.ROOT)
                    .replaceAll("[^\\p{L}]", "");

            if (!normalizedWord.isEmpty()) {
                wordFrequency.merge(normalizedWord, 1, Integer::sum);
            }
        }
    }
}

