import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentMap;
import java.util.concurrent.atomic.AtomicLong;

public class KeyValueStore {
    private final ConcurrentMap<String, String> store = new ConcurrentHashMap<>();
    private final ConcurrentMap<String, AtomicLong> accessCounts = new ConcurrentHashMap<>();
    private final ConcurrentMap<String, AtomicLong> lastAccessTimes = new ConcurrentHashMap<>();
    private final ConcurrentMap<Class<?>, AtomicLong> typeCounts = new ConcurrentHashMap<>();

    public void put(String key, String value) {
        validateKey(key);

        if (value == null) {
            throw new IllegalArgumentException("Value cannot be null");
        }

        store.compute(key, (ignored, previousValue) -> {
            if (previousValue != null) {
                decrementTypeCount(previousValue.getClass());
            }

            incrementTypeCount(value.getClass());
            return value;
        });
    }

    public void putAll(Map<String, String> entries) {
        if (entries == null) {
            throw new IllegalArgumentException("Entries cannot be null");
        }

        for (Map.Entry<String, String> entry : entries.entrySet()) {
            validateKey(entry.getKey());

            if (entry.getValue() == null) {
                throw new IllegalArgumentException("Value cannot be null");
            }
        }

        for (Map.Entry<String, String> entry : entries.entrySet()) {
            put(entry.getKey(), entry.getValue());
        }
    }

    public String get(String key) {
        validateKey(key);

        accessCounts
                .computeIfAbsent(key, ignored -> new AtomicLong())
                .incrementAndGet();

        lastAccessTimes
                .computeIfAbsent(key, ignored -> new AtomicLong())
                .set(System.currentTimeMillis());

        return store.get(key);
    }

    public long getAccessCount(String key) {
        validateKey(key);

        AtomicLong count = accessCounts.get(key);
        return count == null ? 0L : count.get();
    }

    public long getLastAccessTime(String key) {
        validateKey(key);

        AtomicLong lastAccessTime = lastAccessTimes.get(key);
        return lastAccessTime == null ? 0L : lastAccessTime.get();
    }

    public long getTypeCount(Class<?> type) {
        validateType(type);

        AtomicLong count = typeCounts.get(type);
        return count == null ? 0L : count.get();
    }

    public Set<String> findKeysByType(Class<?> type) {
        validateType(type);

        Set<String> matchingKeys = new HashSet<>();

        for (Map.Entry<String, String> entry : store.entrySet()) {
            if (type.isInstance(entry.getValue())) {
                matchingKeys.add(entry.getKey());
            }
        }

        return Collections.unmodifiableSet(matchingKeys);
    }

    public Statistics computeStatistics() {
        Map<Class<?>, Long> typeDistribution = new HashMap<>();
        long estimatedMemoryUsage = 0L;

        for (Map.Entry<String, String> entry : store.entrySet()) {
            Class<?> type = entry.getValue().getClass();
            typeDistribution.merge(type, 1L, Long::sum);
            estimatedMemoryUsage += estimateEntryMemory(entry.getKey(), entry.getValue());
        }

        String keyWithMaxAccess = null;
        long maximumAccessCount = -1L;

        for (String key : store.keySet()) {
            long accessCount = getAccessCount(key);

            if (accessCount > maximumAccessCount
                    || (accessCount == maximumAccessCount
                    && keyWithMaxAccess != null
                    && key.compareTo(keyWithMaxAccess) < 0)) {
                maximumAccessCount = accessCount;
                keyWithMaxAccess = key;
            }
        }

        if (store.isEmpty()) {
            maximumAccessCount = 0L;
        }

        return new Statistics(
                store.size(),
                keyWithMaxAccess,
                typeDistribution,
                estimatedMemoryUsage
        );
    }

    public void clear() {
        store.clear();
        accessCounts.clear();
        lastAccessTimes.clear();
        typeCounts.clear();
    }

    private long estimateEntryMemory(String key, String value) {
        return 32L
                + 24L
                + 24L
                + (2L * key.length())
                + (2L * value.length());
    }

    private void incrementTypeCount(Class<?> type) {
        typeCounts
                .computeIfAbsent(type, ignored -> new AtomicLong())
                .incrementAndGet();
    }

    private void decrementTypeCount(Class<?> type) {
        AtomicLong count = typeCounts.get(type);

        if (count != null) {
            count.decrementAndGet();
        }
    }

    private void validateKey(String key) {
        if (key == null) {
            throw new IllegalArgumentException("Key cannot be null");
        }
    }

    private void validateType(Class<?> type) {
        if (type == null) {
            throw new IllegalArgumentException("Type cannot be null");
        }
    }

    public static final class Statistics {
        private final long totalEntries;
        private final String keyWithMaxAccess;
        private final Map<Class<?>, Long> typeDistribution;
        private final long estimatedMemoryUsage;

        private Statistics(
                long totalEntries,
                String keyWithMaxAccess,
                Map<Class<?>, Long> typeDistribution,
                long estimatedMemoryUsage
        ) {
            this.totalEntries = totalEntries;
            this.keyWithMaxAccess = keyWithMaxAccess;
            this.typeDistribution = Collections.unmodifiableMap(
                    new HashMap<>(typeDistribution)
            );
            this.estimatedMemoryUsage = estimatedMemoryUsage;
        }

        public long getTotalEntries() {
            return totalEntries;
        }

        public String getKeyWithMaxAccess() {
            return keyWithMaxAccess;
        }

        public Map<Class<?>, Long> getTypeDistribution() {
            return typeDistribution;
        }

        public long getEstimatedMemoryUsage() {
            return estimatedMemoryUsage;
        }
    }
}

