public class MachineEntry {
    private String clock;
    private String machine;
    private Map<String, Integer> operationCounts;

    public MachineEntry(String clock, String machine) {
        if (clock == null || clock.trim().isEmpty()) {
            throw new IllegalArgumentException("Clock must not be null or empty");
        }
        if (machine == null || machine.trim().isEmpty()) {
            throw new IllegalArgumentException("Machine must not be null or empty");
