    public Map<String, Object> getOperationStatistics() {
        Map<String, Object> statistics = new HashMap<>();

        int total = 0;
        int maxCount = 0;
        String mostFrequent = null;

        for (Map.Entry<String, Integer> entry : operationCounts.entrySet()) {
            int count = entry.getValue();
            total += count;

            if (count > maxCount) {
                maxCount = count;
                mostFrequent = entry.getKey();
            }
        }

        statistics.put("total", total);
        statistics.put("unique", operationCounts.size());
        statistics.put("mostFrequent", mostFrequent);
        statistics.put("maxCount", maxCount);

        return statistics;
    }
}

