class AdvancedTreeLoader {
    public static <T extends Comparable<T>> void load(
            BinaryTree<T> tree,
            List<T> data,
            boolean shouldSort) {

        if (tree == null) {
            throw new IllegalArgumentException("Tree cannot be null");
        }
        if (data == null) {
            throw new IllegalArgumentException("Data cannot be null");
        }

        if (shouldSort) {
            List<T> sortedData = new ArrayList<>(data);
            Collections.sort(sortedData);
            loadBalanced(tree, sortedData, 0, sortedData.size() - 1);
        } else {
            for (T value : data) {
                tree.insert(value);
            }
        }
    }

    private static <T extends Comparable<T>> void loadBalanced(
            BinaryTree<T> tree,
            List<T> data,
            int start,
            int end) {

        if (start > end) {
            return;
        }

        int middle = start + (end - start) / 2;
        tree.insert(data.get(middle));

        loadBalanced(tree, data, start, middle - 1);
        loadBalanced(tree, data, middle + 1, end);
    }
}

