        clauses.add(new int[]{a, b});
        variables.add(Math.abs(a));
        variables.add(Math.abs(b));

        addImplication(-a, b);
        addImplication(-b, a);
    }

    private void addImplication(int from, int to) {
        graph.computeIfAbsent(from, key -> new java.util.ArrayList<>()).add(to);
        graph.computeIfAbsent(to, key -> new java.util.ArrayList<>());

        reverseGraph.computeIfAbsent(to, key -> new java.util.ArrayList<>()).add(from);
        reverseGraph.computeIfAbsent(from, key -> new java.util.ArrayList<>());
    }

    public boolean isSatisfiable() {
        finishingTimes.clear();
        java.util.Set<Integer> visited = new java.util.HashSet<>();
        int[] time = {0};

