class TwoSatSolver {
    private final java.util.List<int[]> clauses;
    private final java.util.Set<Integer> variables;
    private final java.util.Map<Integer, java.util.List<Integer>> graph;
    private final java.util.Map<Integer, java.util.List<Integer>> reverseGraph;
    private final java.util.Map<Integer, Integer> finishingTimes;
    private final java.util.Map<Integer, Integer> leaders;

    public TwoSatSolver() {
        clauses = new java.util.ArrayList<>();
        variables = new java.util.HashSet<>();
        graph = new java.util.HashMap<>();
        reverseGraph = new java.util.HashMap<>();
        finishingTimes = new java.util.HashMap<>();
        leaders = new java.util.HashMap<>();
    }

    public void addClause(int a, int b) {
        clauses.add(new int[]{a, b});
        variables.add(Math.abs(a));
        variables.add(Math.abs(b));

        addImplication(-a, b);
        addImplication(-b, a);
    }

    private void addImplication(int from, int to) {
        graph.computeIfAbsent(from, key -> new java.util.ArrayList<>()).add(to);
        graph.computeIfAbsent(to, key -> new java.util.ArrayList<>());

        reverseGraph.computeIfAbsent(to, key -> new java.util.ArrayList<>()).add(from);
        reverseGraph.computeIfAbsent(from, key -> new java.util.ArrayList<>());
    }

    public boolean isSatisfiable() {
        finishingTimes.clear();
        leaders.clear();

        java.util.Set<Integer> visited = new java.util.HashSet<>();
        int[] time = {0};

        for (int node : reverseGraph.keySet()) {
            if (!visited.contains(node)) {
                dfsReverse(node, visited, time);
            }
        }

        java.util.List<Integer> nodes = new java.util.ArrayList<>(finishingTimes.keySet());
        nodes.sort((a, b) ->
                Integer.compare(finishingTimes.get(b), finishingTimes.get(a)));

        visited.clear();

        for (int node : nodes) {
            if (!visited.contains(node)) {
                dfsOriginal(node, node, visited);
            }
        }

        for (int variable : variables) {
            Integer positiveLeader = leaders.get(variable);
            Integer negativeLeader = leaders.get(-variable);

            if (positiveLeader != null
                    && positiveLeader.equals(negativeLeader)) {
                return false;
            }
        }

        return true;
    }

    private void dfsReverse(
            int node,
            java.util.Set<Integer> visited,
            int[] time
    ) {
        visited.add(node);

        for (int neighbor : reverseGraph.getOrDefault(
                node,
                java.util.Collections.emptyList()
        )) {
            if (!visited.contains(neighbor)) {
                dfsReverse(neighbor, visited, time);
            }
        }

        finishingTimes.put(node, time[0]++);
    }

    private void dfsOriginal(
            int node,
            int leader,
            java.util.Set<Integer> visited
    ) {
        visited.add(node);
        leaders.put(node, leader);

        for (int neighbor : graph.getOrDefault(
                node,
                java.util.Collections.emptyList()
        )) {
            if (!visited.contains(neighbor)) {
                dfsOriginal(neighbor, leader, visited);
            }
        }
    }
}

