import java.util.PriorityQueue;

class GraphAnalyzer {
    public static Map<String, Object> analyzeGraph(int[][] graph, int source) {
        if (graph == null || graph.length == 0) {
            throw new IllegalArgumentException("Graph must not be null or empty.");
        }

        int n = graph.length;

        for (int[] row : graph) {
            if (row == null || row.length != n) {
                throw new IllegalArgumentException(
                        "Graph must be a square adjacency matrix.");
            }

            for (int weight : row) {
                if (weight < 0) {
                    throw new IllegalArgumentException(
                            "Dijkstra's algorithm does not support negative edge weights.");
                }
            }
        }

        if (source < 0 || source >= n) {
            throw new IllegalArgumentException("Source vertex is out of range.");
        }

        int[] distances = new int[n];
        int[] predecessors = new int[n];

        Arrays.fill(distances, Integer.MAX_VALUE);
        Arrays.fill(predecessors, -1);

        distances[source] = 0;

        PriorityQueue<Vertex> queue = new PriorityQueue<>(
                Comparator.comparingInt(vertex -> vertex.distance)
        );
        queue.offer(new Vertex(source, 0));

        int visitedCount = 0;

        while (!queue.isEmpty()) {
            Vertex current = queue.poll();

            if (current.distance != distances[current.index]) {
                continue;
            }

            visitedCount++;

            for (int neighbor = 0; neighbor < n; neighbor++) {
                int weight = graph[current.index][neighbor];

                // A zero value represents the absence of an edge.
                if (weight == 0 || neighbor == current.index) {
                    continue;
                }

                if (current.distance > Integer.MAX_VALUE - weight) {
                    continue;
                }

                int newDistance = current.distance + weight;

                if (newDistance < distances[neighbor]) {
                    distances[neighbor] = newDistance;
                    predecessors[neighbor] = current.index;
                    queue.offer(new Vertex(neighbor, newDistance));
                }
            }
        }

        List<List<Integer>> paths = new ArrayList<>();
        for (int vertex = 0; vertex < n; vertex++) {
            paths.add(buildPath(source, vertex, predecessors, distances));
        }

        int maxDistance = 0;
        for (int distance : distances) {
            if (distance != Integer.MAX_VALUE && distance > maxDistance) {
                maxDistance = distance;
            }
        }

        Map<String, Object> result = new LinkedHashMap<>();
        result.put("distances", distances);
        result.put("paths", paths);
        result.put("visitedCount", visitedCount);
        result.put("maxDistance", maxDistance);
        return result;
    }

    private static List<Integer> buildPath(
            int source,
            int target,
            int[] predecessors,
            int[] distances) {

        List<Integer> path = new ArrayList<>();

        if (distances[target] == Integer.MAX_VALUE) {
            return path;
        }

        int current = target;
        while (current != -1) {
            path.add(current);

            if (current == source) {
                break;
            }

            current = predecessors[current];
        }

        if (path.get(path.size() - 1) != source) {
            return new ArrayList<>();
        }

        java.util.Collections.reverse(path);
        return path;
    }

    private static class Vertex {
        private final int index;
        private final int distance;

        Vertex(int index, int distance) {
            this.index = index;
            this.distance = distance;
        }
    }
}
